120	// runGrep answers a grep call.
121	func (i *Inspector) runGrep(tc llm.ToolCall) string {
122		var a struct {
123			Pattern    string `json:"pattern"`
124			Glob       string `json:"glob"`
125			Path       string `json:"path"`
126			Mode       string `json:"mode"`
127			IgnoreCase bool   `json:"ignore_case"`
128			Context    int    `json:"context_lines"`
129		}
130		if msg := decodeArgs(tc, &a); msg != "" {
131			return msg
132		}
133		if strings.TrimSpace(a.Pattern) == "" {
134			return "The required \"pattern\" argument was missing."
135		}
136	
137		mode := workspace.GrepFiles
138		modeName := "files"
139		switch a.Mode {
140		case "", "files":
141		case "content":
142			mode, modeName = workspace.GrepContent, "content"
143		case "count":
144			mode, modeName = workspace.GrepCount, "count"
145		default:
146			return fmt.Sprintf("Unknown mode %q. Use \"files\", \"content\", or \"count\".", a.Mode)
147		}
148		if a.Context < 0 {
149			return "context_lines cannot be negative."
150		}
151		if a.Context > maxGrepContext {
152			return fmt.Sprintf("context_lines is capped at %d; ask for fewer, or read the file.", maxGrepContext)
153		}
154		// Asking for context implies wanting to see lines. Returning a file list to
155		// a call that asked for three lines either side would be answering a
156		// question nobody posed, and silently dropping an argument is the shape a
157		// model reads as its request being ignored.
158		if a.Context > 0 && mode != workspace.GrepContent {
159			mode, modeName = workspace.GrepContent, "content"
160		}
161	
162		res, err := i.Files.Grep(workspace.GrepQuery{
163			Pattern: a.Pattern, Glob: a.Glob, Dir: a.Path, Mode: mode,
164			IgnoreCase: a.IgnoreCase, ContextLines: a.Context,
165		})
166		if err != nil {
167			return fmt.Sprintf("The search pattern was not valid: %v", err)
168		}
169		// The scope and the mode go in the line, not just the pattern. They shape
170		// the answer completely — a glob that admits no files turns any pattern into
171		// "no matches" — so a report naming only the pattern blames the wrong
172		// argument, and leaves both the model and the user with nothing to correct.
173		query := fmt.Sprintf("%s%s as %s", quoteToolArg(a.Pattern), grepScope(a.Path, a.Glob), modeName)
174		i.Out.Toolf("Searched for %s — %s", query, matchSummary(res))
175	
176		if len(res.Files) == 0 {
177			return grepNothing(query, res)
178		}
179	
180		var b strings.Builder
181		fmt.Fprintf(&b, "%s for %s.\n\n", matchSummary(res), query)
182		for _, f := range res.Files {
183			switch mode {
184			case workspace.GrepContent:
185				for _, l := range f.Lines {
186					// grep's own convention: ":" for a line the pattern hit, "-"
187					// for one that came along for context, and "--" where the
188					// listing jumps. A model reading twenty lines has to be able to
189					// tell which one it searched for.
190					if l.GapBefore {
191						b.WriteString("--\n")
192					}
193					sep := ":"
194					if !l.Match {
195						sep = "-"
196					}
197					fmt.Fprintf(&b, "%s%s%d%s %s\n", f.Path, sep, l.Number, sep, l.Text)
198				}
199			case workspace.GrepCount:
200				fmt.Fprintf(&b, "%s: %d\n", f.Path, f.Count)
201			case workspace.GrepFiles:
202				fmt.Fprintf(&b, "%s\n", f.Path)
203			}
204		}
205		if res.Truncated.Any() {
206			b.WriteString("\n(Results were cut short by a limit. Narrow the search with glob or path to see the rest.)\n")
207		}
208		// A clipped line ends in "…", but only saying so once makes it a fact about
209		// the search rather than a character that happened to be in the file.
210		if res.Shortened > 0 {
211			// plural carries the count itself; passing it again alongside printed
212			// "49 long 49 lines were shortened". Found by the first real use of
213			// `strument tool grep`, which is the argument for the command.
214			fmt.Fprintf(&b, "\n(%s shortened, marked with \"…\". Read the file for the whole line.)\n",
215				plural(res.Shortened, "long line was", "long lines were"))
216		}
217		return truncateResult(b.String())
218	}
