220	// globSyntaxNote explains the two glob shapes that silently admit nothing. Both
221	// are natural first guesses, and both used to fail to an empty result that named
222	// only the pattern, so a reader concluded the code was not there.
223	const globSyntaxNote = "A glob is matched against the whole path, segment by segment. " +
224		"\"*.go\" therefore matches only files in the project root, and a bare directory name " +
225		"matches nothing at all; use \"**/*.go\" to reach every directory. To search one subtree, " +
226		"grep's \"path\" argument is the direct way to say so."
227	
228	// grepScope renders the part of a search that is not the pattern, so a report
229	// can name it. Empty when the search covered the whole project.
230	func grepScope(dir, glob string) string {
231		var b strings.Builder
232		if d := strings.TrimSpace(dir); d != "" {
233			fmt.Fprintf(&b, " under %s", quoteToolArg(d))
234		}
235		if g := strings.TrimSpace(glob); g != "" {
236			fmt.Fprintf(&b, " matching %s", quoteToolArg(g))
237		}
238		return b.String()
239	}
240	
241	// grepNothing explains an empty result, which is three different situations
242	// that used to be reported as one.
243	//
244	// Saying "no matches" when the scope admitted no files states that the pattern
245	// is absent from the project. Watched live, that is exactly how a model read it
246	// — a search scoped with a directory-shaped glob returned nothing, and the next
247	// step widened the *pattern*, because the pattern was the only thing the report
248	// mentioned. The identifier was in 21 files at the time.
249	func grepNothing(query string, res workspace.GrepResult) string {
250		switch {
251		case res.InScope == 0:
252			return "No files were searched for " + query + ": nothing is in that scope, " +
253				"so the pattern was never tested.\n\n" + globSyntaxNote
254		case res.Scanned == 0:
255			return fmt.Sprintf("No files were searched for %s: %s in that scope, but every one of "+
256				"them is binary or over the size limit.", query, plural(res.InScope, "file is", "files are"))
257		default:
258			return fmt.Sprintf("No matches for %s. %s searched.", query,
259				plural(res.Scanned, "file", "files"))
260		}
261	}
262	
263	// matchSummary describes a search's outcome in one line.
264	func matchSummary(res workspace.GrepResult) string {
265		if len(res.Files) == 0 {
266			return "no matches"
267		}
268		return fmt.Sprintf("%s in %s", plural(res.Total, "match", "matches"), plural(len(res.Files), "file", "files"))
269	}
270	
271	func plural(n int, one, many string) string {
272		if n == 1 {
273			return fmt.Sprintf("%d %s", n, one)
274		}
275		return fmt.Sprintf("%d %s", n, many)
276	}
