363	// runCheckTool runs the configured checks and returns their output.
364	//
365	// It never takes a command, only a name, so nothing the model says can change
366	// what runs. Each check is executed as argv without a shell, the same rule the
367	// git port follows.
368	func (c *Coder) runCheckTool(ctx context.Context, tc llm.ToolCall) string {
369		var a struct {
370			Name string `json:"name"`
371		}
372		if msg := decodeArgs(tc, &a); msg != "" {
373			return msg
374		}
375		if len(c.Check) == 0 {
376			return "No checks are configured for this project."
377		}
378	
379		names := checkNames(c.Check)
380		if name := strings.TrimSpace(a.Name); name != "" {
381			if indexCheck(c.Check, name) < 0 {
382				return fmt.Sprintf("There is no check named %q. Configured checks: %s.",
383					name, strings.Join(names, ", "))
384			}
385			names = []string{name}
386		}
387		// The model asked, so it gets the whole transcript either way — a passing
388		// run is information too.
389		transcript, _ := c.runChecks(ctx, names)
390		return transcript
391	}
392	
393	// runChecks runs the named checks in the order given, stopping at the first
394	// failure. It returns the transcript and whether everything passed.
395	//
396	// Order is the caller's, wherever the list came from: check() uses the order
397	// the checks were declared in, check_auto uses the order that list was written
398	// in. One rule, stated once — checks run in the order they are listed.
399	func (c *Coder) runChecks(ctx context.Context, names []string) (transcript string, passed bool) {
400		var b strings.Builder
401		for _, name := range names {
402			i := indexCheck(c.Check, name)
403			if i < 0 {
404				// Unreachable through either caller: the tool validates the name and
405				// config validates check_auto at load. Report rather than skip, so a
406				// future third caller cannot silently check nothing.
407				fmt.Fprintf(&b, "%s: no such check is configured.\n", name)
408				return truncateResult(b.String()), false
409			}
410			ch := c.Check[i]
411	
412			// The command prints before it runs, because a suite can take a minute
413			// and silence in the middle of a turn reads as a hang. The ‹check› tag
414			// marks the line as the harness announcing a check rather than a
415			// transcript of the model's own words, the same reason ‹shell› prefixes
416			// a confirmation's purpose.
417			c.Out.Toolf("‹check› %s\n$ %s", ch.Name, strings.Join(ch.Argv, " "))
418			exit, output := c.runCheck(ctx, ch)
419			if exit == 0 {
420				// A passing check's output is noise to the user — with check_auto on
421				// it lands on every editing turn and buries the diffs they are here to
422				// read. The model still gets the whole transcript below: to it, what a
423				// passing run printed is information.
424				c.Out.Toolf("passed")
425			} else {
426				// The failure verdict matches the ‹check› line that announced it, but
427				// the output it produced is a model-run transcript of its own and keeps
428				// the plain color.
429				c.Out.Toolf("failed (exit status %d)", exit)
430				if trimmed := strings.TrimRight(output, "\n"); trimmed != "" {
431					c.Out.Printf("%s", trimmed)
432				}
433			}
434	
435			fmt.Fprintf(&b, "%s: %s\nExit status: %d\n", ch.Name, strings.Join(ch.Argv, " "), exit)
436			if strings.TrimSpace(output) != "" {
437				fmt.Fprintf(&b, "Output:\n%s\n", output)
438			}
439			if exit != 0 {
440				// Stop at the first failure: the later checks would mostly report
441				// the same breakage, and the user ordered them so the fast ones
442				// come first.
443				if len(names) > 1 {
444					b.WriteString("\nStopped here; later checks were not run.\n")
445				}
446				return truncateResult(b.String()), false
447			}
448			b.WriteString("\n")
449		}
450		return truncateResult(b.String()), true
451	}
452	
453	// runCheck executes one check's argv, merging stdout and stderr.
454	func (c *Coder) runCheck(ctx context.Context, ch config.Check) (int, string) {
455		// The argv is the user's own configuration, reached by name; the model
456		// never supplies any part of it, which is what makes running it without a
457		// confirmation prompt reasonable.
458		if c.Sandbox.blocksExecution() {
459			return -1, c.Sandbox.refusal()
460		}
461		// The same deadline the bash tool gets, and for the same reason: a check is
462		// model-caused, and a test suite that waits forever on a socket hangs the
463		// session exactly as a bash block would.
464		if d := c.shellTimeout(); d > 0 {
465			var cancel context.CancelFunc
466			ctx, cancel = context.WithTimeout(ctx, d)
467			defer cancel()
468		}
469		cmd := exec.CommandContext(ctx, ch.Argv[0], ch.Argv[1:]...) //nolint:gosec // Argv from the user's config, never from the model.
470		cmd.Dir = c.Root
471		// The argv is trusted, but the output is not selected by it: a failing
472		// test suite happily prints its environment, and that output goes to the
473		// model as a tool result. So checks run under the same allowlist as the
474		// bash tool, rather than inheriting the session's credentials.
475		cmd.Env = FilterEnv(nil, c.EnvAllow)
476		out, err := cmd.CombinedOutput()
477		exit := 0
478		var ee *exec.ExitError
479		switch {
480		case errors.As(err, &ee):
481			exit = ee.ExitCode()
482		case err != nil:
483			return -1, fmt.Sprintf("could not run %s: %v", strings.Join(ch.Argv, " "), err)
484		}
485		if exit != 0 && c.Sandbox.Active && looksDenied(string(out)) {
486			return exit, string(out) + c.Sandbox.deniedHint()
487		}
488		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
489			return -1, string(out) + fmt.Sprintf(
490				"\nThe check was stopped after %s. Strument's `shell_timeout` did it, not the check.", c.shellTimeout())
491		}
492		return exit, string(out)
493	}
494	
495	func indexCheck(checks []config.Check, name string) int {
496		for i, ch := range checks {
497			if ch.Name == name {
498				return i
499			}
500		}
501		return -1
502	}
503	
504	func checkNames(checks []config.Check) []string {
505		out := make([]string, 0, len(checks))
506		for _, ch := range checks {
507			out = append(out, ch.Name)
508		}
509		return out
510	}
511	
512	// truncateResult caps a tool result, saying so rather than cutting silently.
513	func truncateResult(s string) string {
514		if len(s) <= maxToolOutputBytes {
515			return s
516		}
517		return s[:maxToolOutputBytes] + "\n\n(Output was cut short here; it exceeded the size one tool result may carry.)\n"
518	}

