 21	// ProjectConfigName is the project-root dotfile, untrusted by default.
 22	const ProjectConfigName = ".strument.star"
 23	
 24	// Options configures Load. Zero values pick the real environment.
 25	type Options struct {
 26		UserConfigPath string                           // "" => os.UserConfigDir()/strument/config.star
 27		ProjectRoot    string                           // "" => no project config discovery
 28		TrustStorePath string                           // "" => DefaultTrustStorePath()
 29		LookupEnv      func(string) (string, bool)      // nil => os.LookupEnv
 30		Warn           func(format string, args ...any) // nil => stderr
 31	}
