 33	// DefaultUserConfigPath resolves the user config location via
 34	// os.UserConfigDir, which honors XDG_CONFIG_HOME.
 35	func DefaultUserConfigPath() (string, error) {
 36		dir, err := os.UserConfigDir()
 37		if err != nil {
 38			return "", err
 39		}
 40		return filepath.Join(dir, "strument", "config.star"), nil
 41	}
