 91	// defaultSandbox is what `sandbox` means when a config does not say.
 92	//
 93	// On by default, because a protection nobody turns on protects nobody, and
 94	// because this one costs nothing to run under: reads and execution are
 95	// untouched. A user who needs it off writes `sandbox = ""`, which is a
 96	// deliberate, visible, greppable act.
 97	//
 98	// A config can express the same rule itself — `sandbox = "landlock" if
 99	// platform.system == "Linux" else ""` — which is the example the platform
100	// object was added for.
101	func defaultSandbox() string {
102		if runtime.GOOS == "linux" {
103			return SandboxLandlock
104		}
105		return ""
106	}
