108	// shellTimeoutSeconds maps the config's encoding onto the coder's.
109	//
110	// A config says `shell_timeout = 0` to mean "no limit", while the coder's zero
111	// value has to mean "unset, use the default" — every other numeric setting works
112	// that way and a Coder built in a test should not silently run without one. The
113	// two zeroes mean opposite things, so the translation happens here, once, rather
114	// than being carried as a second boolean field to every reader.
115	func shellTimeoutSeconds(n int) int {
116		if n == 0 {
117			return -1
118		}
119		return n
120	}
