122	// ValidEnvAllowName reports whether s is acceptable as an env_allow entry:
123	// a single non-empty word with no "=" (values always come from the real
124	// environment) and no quoting characters — the config and the /env command
125	// share this rule, and neither does shell-style unquoting, so a quoted string
126	// must fail rather than become a name with literal quotes in it.
127	func ValidEnvAllowName(s string) bool {
128		return s != "" && !strings.ContainsAny(s, `="' `)
129	}
