131	// parsePositiveInt reads a Starlark int that must be at least 1.
132	// parseNonNegativeInt is parsePositiveInt where zero carries a meaning of its
133	// own — `shell_timeout = 0` asks for no limit rather than an instant one.
134	func parseNonNegativeInt(path, name string, v starlark.Value) (int, error) {
135		iv, ok := v.(starlark.Int)
136		if !ok {
137			return 0, fmt.Errorf("%s: `%s` must be a non-negative integer, got %s", path, name, v.Type())
138		}
139		n, ok := iv.Int64()
140		if !ok {
141			return 0, fmt.Errorf("%s: `%s` is out of range", path, name)
142		}
143		if n < 0 {
144			return 0, fmt.Errorf("%s: `%s` must not be negative, got %d", path, name, n)
145		}
146		return int(n), nil
147	}
