149	func parsePositiveInt(path, name string, v starlark.Value) (int, error) {
150		iv, ok := v.(starlark.Int)
151		if !ok {
152			return 0, fmt.Errorf("%s: `%s` must be a positive integer, got %s", path, name, v.Type())
153		}
154		n, ok := iv.Int64()
155		if !ok {
156			return 0, fmt.Errorf("%s: `%s` is out of range", path, name)
157		}
158		if n < 1 {
159			return 0, fmt.Errorf("%s: `%s` must be at least 1, got %d", path, name, n)
160		}
161		return int(n), nil
162	}
