164	// parseReasoningDisplay reads `reasoning_display`: "full", a line count, or
165	// "off". Zero lines is "off" — the number says it plainly enough.
166	//
167	// A count and a word share one setting because they answer one question — how
168	// much thinking to show — and splitting them into two keys would let a config
169	// say "off" and "12" at once.
170	func parseReasoningDisplay(path string, v starlark.Value) (ReasoningDisplay, error) {
171		switch val := v.(type) {
172		case starlark.String:
173			switch s := string(val); s {
174			case "full":
175				return ReasoningDisplay{Mode: ReasoningFull}, nil
176			case "off":
177				return ReasoningDisplay{Mode: ReasoningOff}, nil
178			default:
179				return ReasoningDisplay{}, fmt.Errorf(
180					"%s: `reasoning_display` must be \"full\", a number of lines, or \"off\", got %q", path, s)
181			}
182		case starlark.Int:
183			n, ok := val.Int64()
184			if !ok || n > math.MaxInt32 {
185				return ReasoningDisplay{}, fmt.Errorf("%s: `reasoning_display` line count is out of range", path)
186			}
187			if n == 0 {
188				// Zero lines is "off" by the plainest reading of the number, so it
189				// means that rather than failing to load. A second spelling is worth
190				// having when it is the one someone would reach for first.
191				return ReasoningDisplay{Mode: ReasoningOff}, nil
192			}
193			if n < 0 {
194				return ReasoningDisplay{}, fmt.Errorf(
195					"%s: `reasoning_display` cannot be negative; use 0 or \"off\" to hide the thinking", path)
196			}
197			return ReasoningDisplay{Mode: ReasoningCapped, Lines: int(n)}, nil
198		default:
199			return ReasoningDisplay{}, fmt.Errorf(
200				"%s: `reasoning_display` must be \"full\", a number of lines, or \"off\", got %s", path, v.Type())
201		}
202	}
