204	// missingConfigError is the very first thing a new user can see, so it carries
205	// a config they can paste rather than a pointer to one.
206	//
207	// It used to say "see doc/config.md", which is a path in the source tree — and
208	// someone who installed with `go install dbohdan.com/strument/cmd/strument` has
209	// no source tree. The message named a file they did not have, for a program
210	// that would not start until they wrote one. Four lines of Starlark is less
211	// text than the sentence explaining where to find them.
212	//
213	// The slug is a real one that works today; `strument model-config` fills in
214	// context, output limits, and pricing for any other, and it runs before a
215	// config exists, which is exactly when it is needed.
216	func missingConfigError(userPath string) error {
217		//nolint:revive,staticcheck // error-strings: this one is the screen a new
218		// user reads, not a clause another message wraps. Nothing wraps it — Load
219		// returns it, main prints it, the program exits.
220		return fmt.Errorf(`no configuration file yet.
221	
222	Strument has no model database and assumes nothing about which models you have,
223	so it needs a config before it will start. Write this to
224	%s:
225	
226	    openrouter = provider("openrouter", api_key=env("OPENROUTER_API_KEY"))
227	
228	    models = {"mimo": model(openrouter, "xiaomi/mimo-v2.5", context=1050000)}
229	    default = "mimo"
230	
231	then export OPENROUTER_API_KEY and run strument again.
232	
233	"strument model-config <slug>" prints a fuller block — context, output limit,
234	pricing — for any OpenRouter model, and it works before a config exists.
235	The full reference is %s.`,
236			userPath, DocsURL+"/blob/master/doc/config.md")
237	}
238	
239	// DocsURL is the documentation's home for someone who installed the binary and
240	// has no source tree to read it from.
241	const DocsURL = "https://github.com/dbohdan/strument"
242	
243	// Load runs the config pipeline: user config, gated project
244	// config, whole-key merge, post-merge side_model resolution, validation.
245	func Load(opts Options) (*Config, error) {
246		warn := opts.Warn
247		if warn == nil {
248			warn = func(format string, args ...any) {
249				fmt.Fprintf(os.Stderr, format+"\n", args...)
250			}
251		}
252		lookup := opts.LookupEnv
253		if lookup == nil {
254			lookup = os.LookupEnv
255		}
256	
257		userPath := opts.UserConfigPath
258		if userPath == "" {
259			var err error
260			if userPath, err = DefaultUserConfigPath(); err != nil {
261				return nil, err
262			}
263		}
264	
265		// 1. User config — always trusted (the trust root).
266		userSrc, err := os.ReadFile(userPath)
267		if err != nil {
268			if errors.Is(err, os.ErrNotExist) {
269				return nil, missingConfigError(userPath)
270			}
271			return nil, err
272		}
273		user, err := execConfig(userPath, userSrc, lookup, opts.ProjectRoot)
274		if err != nil {
275			return nil, err
276		}
277	
278		// 2-3. Project config — inert unless trusted.
279		var project *fileGlobals
280		if opts.ProjectRoot != "" {
281			projPath := filepath.Join(opts.ProjectRoot, ProjectConfigName)
282			if projSrc, err := os.ReadFile(projPath); err == nil {
283				absPath, err := filepath.Abs(projPath)
284				if err != nil {
285					return nil, err
286				}
287				tsPath := opts.TrustStorePath
288				if tsPath == "" {
289					if tsPath, err = DefaultTrustStorePath(); err != nil {
290						return nil, err
291					}
292				}
293				ts, err := OpenTrustStore(tsPath)
294				if err != nil {
295					return nil, err
296				}
297				if ts.IsTrusted(absPath, projSrc) {
298					if project, err = execConfig(projPath, projSrc, lookup, opts.ProjectRoot); err != nil {
299						return nil, err
300					}
301				} else {
302					warn("Ignoring untrusted project config %s.", projPath)
303					warn("Run `strument trust` to allow it. Re-trust after every edit.")
304				}
305			} else if !errors.Is(err, os.ErrNotExist) {
306				return nil, err
307			}
308		}
309	
310		// 4. Merge: models whole-key, project wins; default and history_file
311		// project-over-user.
312		// The sandbox is on by default where it can be, and the default is set
313		// here rather than at the point of use so `strument model-config` and any
314		// other reader sees the same answer the session will act on.
315		cfg := &Config{Models: map[string]*Model{}, Sandbox: defaultSandbox()}
316		maps.Copy(cfg.Models, user.models)
317		if user.hasDefault {
318			cfg.Default = user.defaultVal
319		}
320		if user.hasHistoryFile {
321			cfg.HistoryFile = user.historyFile
322		}
323		if user.hasProxy {
324			cfg.Proxy = user.proxyVal
325		}
326		if user.hasScraper {
327			cfg.Scraper = user.scraperVal
328		}
329		if user.hasCheck {
330			cfg.Check = user.checkVal
331		}
332		if user.hasCheckAuto {
333			cfg.CheckAuto = user.checkAutoVal
334		}
335		if user.hasReasoningDisplay {
336			cfg.ReasoningDisplay = user.reasoningDisplayVal
337		}
338		if user.hasMaxSteps {
339			cfg.MaxSteps = user.maxStepsVal
340		}
341		if user.hasMaxErrorReflections {
342			cfg.MaxErrorReflections = user.maxErrorReflectionsVal
343		}
344		if user.hasWebfetchAllow {
345			cfg.WebfetchAllow = user.webfetchAllowVal
346		}
347		if user.hasWebSearch {
348			cfg.WebSearch = user.webSearchVal
349		}
350		if user.hasLoopDetection {
351			cfg.NoLoopDetection = !user.loopDetectionVal
352		}
353		if user.hasSandbox {
354			cfg.Sandbox = user.sandboxVal
355		}
356		if user.hasSandboxWrite {
357			cfg.SandboxWrite = user.sandboxWriteVal
358		}
359		if user.hasShellTimeout {
360			cfg.ShellTimeout = shellTimeoutSeconds(user.shellTimeoutVal)
361		}
362		if user.hasGitSign {
363			cfg.GitSign = user.gitSignVal
364		}
365		if user.hasEnvAllow {
366			cfg.EnvAllow = user.envAllowVal
367		}
368		if user.hasEnvSet {
369			cfg.EnvSet = user.envSetVal
370		}
371		if project != nil {
372			maps.Copy(cfg.Models, project.models)
373			if project.hasDefault {
374				cfg.Default = project.defaultVal
375			}
376			if project.hasHistoryFile {
377				cfg.HistoryFile = project.historyFile
378			}
379			if project.hasProxy {
380				cfg.Proxy = project.proxyVal
381			}
382			if project.hasScraper {
383				cfg.Scraper = project.scraperVal
384			}
385			if project.hasCheck {
386				// Per-key rather than wholesale, so a project can override one check
387				// or add its own without restating the user's whole set.
388				cfg.Check = mergeChecks(cfg.Check, project.checkVal)
389			}
390			if project.hasCheckAuto {
391				// Whole-value, unlike check: this is one ordered decision about what
392				// runs unattended, and merging two such lists element-wise would give
393				// an order nobody wrote.
394				cfg.CheckAuto = project.checkAutoVal
395			}
396			if project.hasReasoningDisplay {
397				cfg.ReasoningDisplay = project.reasoningDisplayVal
398			}
399			if project.hasMaxSteps {
400				cfg.MaxSteps = project.maxStepsVal
401			}
402			if project.hasMaxErrorReflections {
403				cfg.MaxErrorReflections = project.maxErrorReflectionsVal
404			}
405			// Whole-value like env_allow and for the same reason: this is one
406			// decision about which hosts stop being asked about, and a project must
407			// be able to narrow what the user's config widened. The trust gate is
408			// what makes a project's entry the user's own decision.
409			if project.hasWebfetchAllow {
410				cfg.WebfetchAllow = project.webfetchAllowVal
411			}
412			// A trusted project may point search at its own instance, or unset it.
413			if project.hasWebSearch {
414				cfg.WebSearch = project.webSearchVal
415			}
416			if project.hasLoopDetection {
417				cfg.NoLoopDetection = !project.loopDetectionVal
418			}
419			if project.hasSandbox {
420				cfg.Sandbox = project.sandboxVal
421			}
422			if project.hasSandboxWrite {
423				cfg.SandboxWrite = project.sandboxWriteVal
424			}
425			if project.hasShellTimeout {
426				cfg.ShellTimeout = shellTimeoutSeconds(project.shellTimeoutVal)
427			}
428			if project.hasGitSign {
429				cfg.GitSign = project.gitSignVal
430			}
431			// Whole-value like check_auto, not per-element: this is one decision
432			// about what the model's commands may see, and a project's word must be
433			// able to narrow what the user's config widened — merging the two lists
434			// could only ever widen.
435			if project.hasEnvAllow {
436				cfg.EnvAllow = project.envAllowVal
437			}
438			// Per-entry, unlike env_allow, and for the opposite reason: env_allow is
439			// one decision about what the model may see, which a project must be
440			// able to narrow wholesale. env_set is a bag of independent settings, so
441			// a project naming TZ should not silently drop the user's GOFLAGS.
442			if project.hasEnvSet {
443				if cfg.EnvSet == nil {
444					cfg.EnvSet = map[string]string{}
445				}
446				maps.Copy(cfg.EnvSet, project.envSetVal)
447			}
448		}
449	
450		// 5. Resolve side_model refs post-merge; nil => self, permanently.
451		for alias, m := range cfg.Models {
452			switch ref := m.sideRef.(type) {
453			case nil:
454				m.SideModel = m
455			case string:
456				target, ok := cfg.Models[ref]
457				if !ok {
458					return nil, fmt.Errorf("model %q: side_model alias %q not found in merged models", alias, ref)
459				}
460				m.SideModel = target
461			case *Model:
462				if ref.SideModel == nil {
463					ref.SideModel = ref // inline side models are their own side model
464				}
465				m.SideModel = ref
466			}
467			m.sideRef = nil
468		}
469	
470		// 5b. Resolve each provider's proxy against the global fallback, once per
471		// distinct *Model — aliases and inline side models repeat pointers, and the
472		// "direct"->inherit rewrite is not idempotent. "direct" forces a direct
473		// connection; an unset provider proxy inherits the global one.
474		if cfg.Proxy == "direct" {
475			return nil, errors.New("global `proxy` cannot be \"direct\" (leave it unset for no proxy)")
476		}
477		if _, err := httpx.ProxyTransport(cfg.Proxy); err != nil {
478			return nil, fmt.Errorf("global %w", err)
479		}
480		resolvedProxy := map[*Model]bool{}
481		resolveProxy := func(alias string, m *Model) error {
482			if m == nil || resolvedProxy[m] {
483				return nil
484			}
485			resolvedProxy[m] = true
486			switch m.Provider.Proxy {
487			case "direct":
488				m.Provider.Proxy = ""
489			case "":
490				m.Provider.Proxy = cfg.Proxy
491			}
492			if _, err := httpx.ProxyTransport(m.Provider.Proxy); err != nil {
493				return fmt.Errorf("model %q provider %w", alias, err)
494			}
495			return nil
496		}
497		// The search backend resolves the same way, because it is the same kind of
498		// egress: non-provider, and inheriting the global proxy unless it says
499		// otherwise. "direct" matters more here than anywhere else — a self-hosted
500		// instance is usually on localhost or the LAN, and a proxy configured for
501		// external traffic has no business carrying that request.
502		if ws := cfg.WebSearch; ws != nil {
503			switch ws.Proxy {
504			case "direct":
505				ws.Proxy = ""
506			case "":
507				ws.Proxy = cfg.Proxy
508			}
509			if _, err := httpx.ProxyTransport(ws.Proxy); err != nil {
510				return nil, fmt.Errorf("websearch %w", err)
511			}
512		}
513		for alias, m := range cfg.Models {
514			if err := resolveProxy(alias, m); err != nil {
515				return nil, err
516			}
517			if err := resolveProxy(alias, m.SideModel); err != nil {
518				return nil, err
519			}
520		}
521	
522		// 6. Validate.
523		if len(cfg.Models) == 0 {
524			return nil, errors.New("config declares no models (the `models` dict is empty)")
525		}
526		if cfg.Default == "" {
527			return nil, errors.New("config sets no `default` model alias")
528		}
529		if _, ok := cfg.Models[cfg.Default]; !ok {
530			return nil, fmt.Errorf("default model alias %q is not a key of `models`", cfg.Default)
531		}
532		// Validated after the merge, since a project may supply the check a user's
533		// check_auto names, or vice versa. A typo here would otherwise mean the
534		// harness silently runs nothing — the one failure mode this feature
535		// exists to prevent.
536		for _, name := range cfg.CheckAuto {
537			if indexCheck(cfg.Check, name) < 0 {
538				known := "none are configured"
539				if len(cfg.Check) > 0 {
540					known = "configured checks: " + strings.Join(cfg.CheckNames(), ", ")
541				}
542				return nil, fmt.Errorf("`check_auto` names %q, which is not a `check` entry (%s)", name, known)
543			}
544		}
545		// Adapter, edit_format, and extra_params were validated at
546		// construction time by the builtins.
547	
548		return cfg, nil
549	}
