551	// predeclaredGlobals is everything a config file can reach without defining it.
552	// Factored out of execConfig so the set has one definition and a test can
553	// evaluate an expression against exactly what a real config sees.
554	func predeclaredGlobals(lookup func(string) (string, bool), root string) starlark.StringDict {
555		return starlark.StringDict{
556			"provider": starlark.NewBuiltin("provider", builtinProvider),
557			"model":    starlark.NewBuiltin("model", builtinModel),
558			"search":   starlark.NewBuiltin("search", builtinSearch),
559			"env":      builtinEnv(lookup),
560			// The project's root, not the config file's directory, in both configs:
561			// a user-level `check = project_checks()` should adapt to whatever
562			// project the session opened.
563			"project_checks": builtinProjectChecks(root),
564			// Read-only facts about the host, so a config can branch on the OS —
565			// the sandbox setting is the first thing that needs to.
566			"platform": platformValue{},
567		}
568	}
569	
570	// execConfig executes one Starlark file with the builtins predeclared and
571	// extracts the required globals.
572	func execConfig(path string, src []byte, lookup func(string) (string, bool), root string) (*fileGlobals, error) {
573		thread := &starlark.Thread{Name: path}
574		predeclared := predeclaredGlobals(lookup, root)
575		fileOpts := &syntax.FileOptions{
576			Set:             true,
577			While:           false,
578			TopLevelControl: true,
579			GlobalReassign:  false,
580			Recursion:       false,
581		}
582		globals, err := starlark.ExecFileOptions(fileOpts, thread, path, src, predeclared)
583		if err != nil {
584			var evalErr *starlark.EvalError
585			if errors.As(err, &evalErr) {
586				return nil, fmt.Errorf("%s: %s", path, evalErr.Backtrace())
587			}
588			return nil, err
589		}
590	
591		out := &fileGlobals{models: map[string]*Model{}}
592	
593		// Both globals are optional per file; the merged result is validated in
594		// Load (a project config may override only `default`, or only aliases).
595		if modelsV, ok := globals["models"]; ok {
596			dict, ok := modelsV.(*starlark.Dict)
597			if !ok {
598				return nil, fmt.Errorf("%s: `models` must be a dict, got %s", path, modelsV.Type())
599			}
600			for k, v := range dict.Entries() {
601				alias, ok := starlark.AsString(k)
602				if !ok {
603					return nil, fmt.Errorf("%s: `models` key %s is not a string", path, k.String())
604				}
605				mv, ok := v.(*modelValue)
606				if !ok {
607					return nil, fmt.Errorf("%s: models[%q] is not a model value (got %s)", path, alias, v.Type())
608				}
609				out.models[alias] = mv.m
610			}
611		}
612	
613		if defaultV, ok := globals["default"]; ok {
614			s, ok := starlark.AsString(defaultV)
615			if !ok {
616				return nil, fmt.Errorf("%s: `default` must be a string alias, got %s", path, defaultV.Type())
617			}
618			out.hasDefault = true
619			out.defaultVal = s
620		}
621	
622		if hv, ok := globals["history_file"]; ok {
623			s, ok := starlark.AsString(hv)
624			if !ok {
625				return nil, fmt.Errorf("%s: `history_file` must be a string path, got %s", path, hv.Type())
626			}
627			out.hasHistoryFile = true
628			out.historyFile = s
629		}
630	
631		if pv, ok := globals["proxy"]; ok {
632			s, ok := starlark.AsString(pv)
633			if !ok {
634				return nil, fmt.Errorf("%s: `proxy` must be a string URL, got %s", path, pv.Type())
635			}
636			out.hasProxy = true
637			out.proxyVal = s
638		}
639	
640		if sv, ok := globals["scraper"]; ok {
641			list, ok := sv.(*starlark.List)
642			if !ok {
643				return nil, fmt.Errorf("%s: `scraper` must be a list of strings (argv, with %%s for the URL), got %s", path, sv.Type())
644			}
