887	// parseChecks decodes the top-level `check` dict: check name -> argv. Starlark
888	// dicts iterate in insertion order, so the declared order is preserved and
889	// meaningful — a bare check run stops at the first failure, so fast checks go
890	// first.
891	func parseChecks(path string, v starlark.Value) ([]Check, error) {
892		dict, ok := v.(*starlark.Dict)
893		if !ok {
894			return nil, fmt.Errorf(
895				"%s: `check` must be a dict of name -> argv list, e.g. {\"test\": [\"go\", \"test\", \"./...\"]}, got %s",
896				path, v.Type())
897		}
898		checks := make([]Check, 0, dict.Len())
899		for _, item := range dict.Items() {
900			name, ok := starlark.AsString(item[0])
901			if !ok {
902				return nil, fmt.Errorf("%s: `check` keys must be strings, got %s", path, item[0].Type())
903			}
904			if strings.TrimSpace(name) == "" {
905				return nil, fmt.Errorf("%s: `check` has an empty check name", path)
906			}
907			list, ok := item[1].(*starlark.List)
908			if !ok {
909				return nil, fmt.Errorf("%s: `check[%q]` must be a list of strings (argv), got %s", path, name, item[1].Type())
910			}
911			argv := make([]string, 0, list.Len())
912			for i := range list.Len() {
913				s, ok := starlark.AsString(list.Index(i))
914				if !ok {
915					return nil, fmt.Errorf("%s: `check[%q]`[%d] must be a string, got %s", path, name, i, list.Index(i).Type())
916				}
917				argv = append(argv, s)
918			}
919			if len(argv) == 0 {
920				return nil, fmt.Errorf("%s: `check[%q]` must not be empty", path, name)
921			}
922			checks = append(checks, Check{Name: name, Argv: argv})
923		}
924		return checks, nil
925	}
