927	// mergeChecks applies the project's checks over the user's: a shared name is
928	// replaced in place, keeping the user's ordering, and a project-only name is
929	// appended. This is the ordered form of the whole-key merge `models` uses.
930	func mergeChecks(user, project []Check) []Check {
931		out := slices.Clone(user)
932		for _, p := range project {
933			if i := slices.IndexFunc(out, func(c Check) bool { return c.Name == p.Name }); i >= 0 {
934				out[i] = p
935				continue
936			}
937			out = append(out, p)
938		}
939		return out
940	}
