942	// TrustProject computes the project config's multihash and records it in
943	// the trust store; the `strument trust` command calls this.
944	//
945	// A project with no config returns ("", nil) rather than an error. That used to
946	// be a failure, and stopped being one when a project could carry skills and no
947	// config.star: `strument trust` is a command about a project, not about one
948	// file, so having nothing of one kind to trust is not a reason to refuse.
949	func TrustProject(projectRoot, trustStorePath string) (string, error) {
950		projPath := filepath.Join(projectRoot, ProjectConfigName)
951		if _, err := os.Stat(projPath); errors.Is(err, os.ErrNotExist) {
952			return "", nil
953		}
954		if err := TrustFiles([]string{projPath}, trustStorePath); err != nil {
955			return "", err
956		}
957		return filepath.Abs(projPath)
958	}
959	
960	// TrustFiles records each path's current content in the trust store, so a
961	// later read of that exact content is trusted and an edited one is not.
962	//
963	// The store is keyed by absolute path and knows nothing about what a file is
964	// for, which is why config and skills share it rather than needing a second
965	// store or a second command: a repository's config and its skills come from
966	// the same author, so they are one trust decision.
967	func TrustFiles(paths []string, trustStorePath string) error {
968		if len(paths) == 0 {
969			return nil
970		}
971		if trustStorePath == "" {
972			var err error
973			if trustStorePath, err = DefaultTrustStorePath(); err != nil {
974				return err
975			}
976		}
977		ts, err := OpenTrustStore(trustStorePath)
978		if err != nil {
979			return err
980		}
981		for _, p := range paths {
982			src, err := os.ReadFile(p)
983			if err != nil {
984				return err
985			}
986			abs, err := filepath.Abs(p)
987			if err != nil {
988				return err
989			}
990			if err := ts.Trust(abs, src); err != nil {
991				return err
992			}
993		}
994		return nil
995	}

