241	// grepNothing explains an empty result, which is three different situations
242	// that used to be reported as one.
243	//
244	// Saying "no matches" when the scope admitted no files states that the pattern
245	// is absent from the project. Watched live, that is exactly how a model read it
246	// — a search scoped with a directory-shaped glob returned nothing, and the next
247	// step widened the *pattern*, because the pattern was the only thing the report
248	// mentioned. The identifier was in 21 files at the time.
249	func grepNothing(query string, res workspace.GrepResult) string {
250		switch {
251		case res.InScope == 0:
252			return "No files were searched for " + query + ": nothing is in that scope, " +
253				"so the pattern was never tested.\n\n" + globSyntaxNote
254		case res.Scanned == 0:
255			return fmt.Sprintf("No files were searched for %s: %s in that scope, but every one of "+
256				"them is binary or over the size limit.", query, plural(res.InScope, "file is", "files are"))
257		default:
258			return fmt.Sprintf("No matches for %s. %s searched.", query,
259				plural(res.Scanned, "file", "files"))
260		}
261	}
