332		i.Out.Toolf("Listed %s (%s)", dir, plural(len(entries), "entry", "entries"))
333	
334		if len(entries) == 0 {
335			return displayDir(a.Path) + " is empty."
336		}
337		var b strings.Builder
338		fmt.Fprintf(&b, "%s:\n\n", displayDir(a.Path))
339		for _, e := range entries {
340			switch {
341			case e.IsDir:
342				fmt.Fprintf(&b, "%s/\n", e.Path)
343			case e.Link != "":
344				// Named the way ls -l names it. Without this a symlink and its
345				// target read as two identical files, and a model shown both spends
346				// the turn deciding which one is meant — observed live, on a
347				// dotfiles directory where aliases.sh links to real/aliases.sh.
348				fmt.Fprintf(&b, "%s -> %s\n", e.Path, e.Link)
